let cart = [];

function isOutOfStock(product) {
  return String(product.stock).toUpperCase() === "OUT OF STOCK" || Number(product.stock) === 0;
}

function getImage(product) {
  return product.image && product.image.trim() !== ""
    ? product.image
    : "https://via.placeholder.com/300x300?text=Add+Image";
}

function renderCategories() {
  const categoryBox = document.getElementById("categoryButtons");
  const categories = ["all", ...new Set(products.map(p => p.category))];

  categoryBox.innerHTML = categories.map(cat => `
    <button onclick="filterProducts('${cat}')">${cat === "all" ? "All" : cat}</button>
  `).join("");
}

function showProducts(list = products) {
  const productBox = document.getElementById("products");

  productBox.innerHTML = list.map((product, index) => {
    const out = isOutOfStock(product);
    const img = getImage(product);

    return `
      <div class="card ${out ? "out-card" : ""}" data-name="${product.name.toLowerCase()}" data-category="${product.category}">
        ${out
          ? `<img src="${img}" alt="${product.name}" onerror="this.src='https://via.placeholder.com/300x300?text=Image+Not+Found'">`
          : `<a href="${img}" target="_blank">
               <img src="${img}" alt="${product.name}" onerror="this.src='https://via.placeholder.com/300x300?text=Image+Not+Found'">
             </a>`
        }

        <h3>${product.name}</h3>
        <p class="price">₹${product.price}</p>

        <p class="${out ? "out-stock" : "stock"}">
          ${out ? "OUT OF STOCK" : "Stock: " + product.stock}
        </p>

        <button class="buy" onclick="${out ? "return false" : `buyStatic(${index})`}">
          ${out ? "Not Available" : "Order on WhatsApp"}
        </button>
      </div>
    `;
  }).join("");
}

function filterProducts(category) {
  if (category === "all") {
    showProducts(products);
  } else {
    showProducts(products.filter(p => p.category === category));
  }
}

function searchProducts() {
  const q = document.getElementById("search").value.toLowerCase();
  const result = products.filter(p => p.name.toLowerCase().includes(q));
  showProducts(result);
}

function buyStatic(index) {
  const product = products[index];

  if (isOutOfStock(product)) {
    alert("Ye product OUT OF STOCK hai");
    return;
  }

  const msg = encodeURIComponent(
    "Hello bhai, mujhe ye product chahiye:\n" +
    "Product: " + product.name + "\n" +
    "Price: ₹" + product.price
  );

  window.open("https://wa.me/" + whatsappNumber + "?text=" + msg, "_blank");
}

function addToCart(index) {
  const product = products[index];

  if (isOutOfStock(product)) {
    alert("Ye product OUT OF STOCK hai");
    return;
  }

  cart.push(product);
  updateCart();
}

function updateCart() {
  document.getElementById("cartCount").innerText = cart.length;

  const cartItems = document.getElementById("cartItems");
  cartItems.innerHTML = cart.map(item => `
    <p>${item.name} - ₹${item.price}</p>
  `).join("");
}

function openCart() {
  document.getElementById("cartBox").style.display = "block";
}

function closeCart() {
  document.getElementById("cartBox").style.display = "none";
}

function sendCartWhatsApp() {
  if (cart.length === 0) {
    alert("Cart empty hai");
    return;
  }

  let msg = "Hello bhai, mujhe ye products chahiye:%0A";
  cart.forEach(item => {
    msg += `%0AProduct: ${item.name} - ₹${item.price}`;
  });

  window.open("https://wa.me/" + whatsappNumber + "?text=" + msg, "_blank");
}

renderCategories();
showProducts();
